    // \u542f\u7528 ISR \u671f\u95f4\u7684\u5f15\u811a\u8109\u51b2  \n#define SAMPLES 800\n#endif\n\nmic_config_t mic_config{\n  .channel_cnt = 1,\n  .sampling_rate = 16000,\n  .buf_size = 1600,\n#if defined(WIO_TERMINAL)\n  .debug_pin = 1                // \u6bcf\u6b21 DAC ISR \u5207\u6362\uff08\u5982\u679c DEBUG \u8bbe\u7f6e\u4e3a 1\uff09\n#elif defined(ARDUINO_ARCH_NRF52840)\n  .debug_pin = LED_BUILTIN      // \u6bcf\u6b21 DAC ISR \u5207\u6362\uff08\u5982\u679c DEBUG \u8bbe\u7f6e\u4e3a 1\uff09\n#elif defined(ARDUINO_SILABS)\n  .debug_pin = LED_BUILTIN      // \u6bcf\u6b21 DAC ISR \u5207\u6362\uff08\u5982\u679c DEBUG \u8bbe\u7f6e\u4e3a 1\uff09  \n#endif\n};\n\n#if defined(WIO_TERMINAL)\nDMA_ADC_Class Mic(&mic_config);\n#elif defined(ARDUINO_ARCH_NRF52840)\nNRF52840_ADC_Class Mic(&mic_config);\n#elif defined(ARDUINO_SILABS)\nMG24_ADC_Class Mic(&mic_config);\n#endif\n\nint16_t recording_buf[SAMPLES];\nvolatile uint8_t recording = 0;\nvolatile static bool record_ready = false;\n\n#if defined(WIO_TERMINAL)\nFilterBuHp filter;\n#endif\n\nvoid setup() {\n\n  Serial.begin(115200);\n  while (!Serial) {delay(10);}\n  \n#if defined(WIO_TERMINAL)  \n  pinMode(WIO_KEY_A, INPUT_PULLUP);\n#endif\n\n  Mic.set_callback(audio_rec_callback);\n\n  if (!Mic.begin()) {\n    Serial.println("\u9ea6\u514b\u98ce\u521d\u59cb\u5316\u5931\u8d25");\n    while (1);\n  }\n\n  Serial.println("\u9ea6\u514b\u98ce\u521d\u59cb\u5316\u5b8c\u6210\u3002");\n\n}\n\nvoid loop() { \n\n#if defined(WIO_TERMINAL)  \nif (digitalRead(WIO_KEY_A) == LOW && !recording) {\n\n    Serial.println("\u5f00\u59cb\u91c7\u6837");\n    recording = 1;\n    record_ready = false;  \n}\n#endif\n\n#if defined(WIO_TERMINAL)  \n  if (!recording && record_ready)\n#elif defined(ARDUINO_ARCH_NRF52840) || defined(ARDUINO_SILABS)\n  if (record_ready)\n#endif  \n  {\n  Serial.println("\u91c7\u6837\u5b8c\u6210");\n  \n  for (int i = 0; i < SAMPLES; i++) {\n    \n  //int16_t sample = filter.step(recording_buf[i]);\n  int16_t sample = recording_buf[i];\n  Serial.println(sample);\n  }\n  \n  record_ready = false; \n  }\n}\n\nstatic void audio_rec_callback(uint16_t *buf, uint32_t buf_len) {\n  \n  static uint32_t idx = 0;\n  // \u4ece DMA \u7f13\u51b2\u533a\u590d\u5236\u6837\u672c\u5230\u63a8\u7406\u7f13\u51b2\u533a\n#if defined(WIO_TERMINAL)\n  if (recording) \n#endif\n  {\n    for (uint32_t i = 0; i < buf_len; i++) {\n  \n      // \u5c06 12 \u4f4d\u65e0\u7b26\u53f7 ADC \u503c\u8f6c\u6362\u4e3a 16 \u4f4d PCM\uff08\u6709\u7b26\u53f7\uff09\u97f3\u9891\u503c\n#if defined(WIO_TERMINAL)\n      recording_buf[idx++] = filter.step((int16_t)(buf[i] - 1024) * 16);\n      //recording_buf[idx++] = (int16_t)(buf[i] - 1024) * 16;  \n#elif defined(ARDUINO_ARCH_NRF52840) || defined(ARDUINO_SILABS)\n      recording_buf[idx++] = buf[i];\n#endif\n\n      if (idx >= SAMPLES){ \n      idx = 0;\n      recording = 0;\n      record_ready = true;\n      break;\n     } \n    }\n  }\n\n}\n')),(0,a.yg)("h3",{id:"\u529f\u80fd\u6982\u8ff0-1"},"\u529f\u80fd\u6982\u8ff0"),(0,a.yg)("p",null,(0,a.yg)("strong",{parentName:"p"},"\u9ea6\u514b\u98ce\u914d\u7f6e")),(0,a.yg)("pre",null,(0,a.yg)("code",{parentName:"pre",className:"language-cpp"},"mic_config_t mic_config{\n  .channel_cnt = 1, // \u8bbe\u7f6e\u4e3a 1 \u8868\u793a\u5355\u58f0\u9053\n  .sampling_rate = 16000, // \u8bbe\u7f6e\u91c7\u6837\u9891\u7387\u4e3a 16000 Hz\n  .buf_size = 1600, // \u8bbe\u7f6e\u7f13\u51b2\u533a\u5927\u5c0f\u4e3a 1600\n  #if defined(WIO_TERMINAL)\n  .debug_pin = 1 // WIO Terminal \u5e73\u53f0\u7684\u8c03\u8bd5\u5f15\u811a\n  #elif defined(ARDUINO_ARCH_NRF52840)\n  .debug_pin = LED_BUILTIN // NRF52840 \u5e73\u53f0\u7684\u8c03\u8bd5\u5f15\u811a\n  #elif defined(ARDUINO_SILABS)\n  .debug_pin = LED_BUILTIN // Silabs \u5e73\u53f0\u7684\u8c03\u8bd5\u5f15\u811a\n  #endif\n};\n")),(0,a.yg)("ul",null,(0,a.yg)("li",{parentName:"ul"},(0,a.yg)("inlineCode",{parentName:"li"},"mic_config_t"),"\uff1a\u5b9a\u4e49\u9ea6\u514b\u98ce\u914d\u7f6e\u7ed3\u6784\u4f53\u3002"),(0,